addonRouter.post('/uninstalled', atlassianAddon.authenticate(), async (req, res, next) => {
        // pass the event on to the framework
        next();
        // proceed to handle internal logic
        const { key: appKey, clientKey } = req.body;
        try {
            const dbService = new OrgBitbucketAppInstallationsDBService();
            const orgId = await dbService.getInstallationsOrgId(appKey, clientKey);
            await dbService.deleteInstallation(appKey, clientKey);
            sendBitbucketAppInstallationTelemetry(BitbucketAppInstallationMetrics.Uninstalled, { appKey, clientKey }, orgId);
            if (orgId) {
                await new ConnectorsService(orgId).removeBitbucketAppInstallationCredentials();
            }
            logger.info(`[uninstalled] handled event for appKey: ${appKey}, clientKey: ${clientKey}, orgId: ${orgId}`);
        } catch (e) {
            logger.error(`[uninstalled] unable to handle event for appKey: ${appKey}, clientKey: ${clientKey}, e: ${stringifyError(e)}`);
        }
    });

static noCacheJson (req, res, next) {
  res.header('Cache-Control', 'no-cache, private, no-store, must-revalidate, max-stale=0, post-check=0, pre-check=0');
  res.header('Content-Type', 'application/json');
  res.header('X-Content-Type-Options', 'nosniff');
  return next();
}
